public sealed class IdempotencyMiddleware(RequestDelegate next, IConnectionMultiplexer redis)
{
    public async Task InvokeAsync(HttpContext context)
    {
        if (HttpMethods.IsPost(context.Request.Method) &&
            context.Request.Headers.TryGetValue("Idempotency-Key", out var key))
        {
            var db = redis.GetDatabase();
            var cacheKey = $"idempotency:{key}";
            var cached = await db.StringGetAsync(cacheKey);
            if (cached.HasValue)
            {
                context.Response.StatusCode = StatusCodes.Status201Created;
                context.Response.ContentType = "application/json";
                await context.Response.WriteAsync(cached!);
                return;
            }

            var originalBody = context.Response.Body;
            await using var buffer = new MemoryStream();
            context.Response.Body = buffer;
            await next(context);

            if (context.Response.StatusCode == StatusCodes.Status201Created)
            {
                buffer.Position = 0;
                var body = await new StreamReader(buffer).ReadToEndAsync();
                await db.StringSetAsync(cacheKey, body, TimeSpan.FromHours(24));
            }
            buffer.Position = 0;
            await buffer.CopyToAsync(originalBody);
            context.Response.Body = originalBody;
            return;
        }
        await next(context);
    }
}

[HttpGet("{id:guid}")]
public async Task<IActionResult> GetProduct(Guid id, CancellationToken ct)
{
    var product = await repo.GetAsync(id, ct);
    if (product is null) return NotFound();

    var etag = product.RowVersion.ToString();
    if (Request.Headers.IfNoneMatch == etag)
        return StatusCode(StatusCodes.Status304NotModified);

    Response.Headers.ETag = etag;
    Response.Headers.CacheControl = "private, max-age=60";
    return Ok(product);
}

