public async Task<ChargeResult> ChargeAsync(ChargeRequest req, string idempotencyKey, CancellationToken ct)
{
    var hash = ComputeHash(req);
    var existing = await store.GetAsync(idempotencyKey, ct);
    if (existing is not null)
    {
        if (existing.RequestHash != hash)
            throw new IdempotencyConflictException(idempotencyKey);
        return existing.Result; // replay
    }

    var result = await gateway.ChargeAsync(req, ct);
    await store.SaveAsync(idempotencyKey, hash, result, TimeSpan.FromHours(48), ct);
    return result;
}
